package com.asmj.marketplace.jobs;
import java.time.Instant;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="job_employer_profiles")
public class EmployerProfile {
 @Id private String id; private String userId; private String ownerName; private String email; private String mobile; private String organisationName; private String organisationType; private String website; private String description; private String address; private String city; private String state; private String pinCode; private String status="PENDING"; private String adminNote; private Instant createdAt=Instant.now(); private Instant reviewedAt;
 public String getId(){return id;} public void setId(String v){id=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getOwnerName(){return ownerName;} public void setOwnerName(String v){ownerName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getMobile(){return mobile;} public void setMobile(String v){mobile=v;} public String getOrganisationName(){return organisationName;} public void setOrganisationName(String v){organisationName=v;} public String getOrganisationType(){return organisationType;} public void setOrganisationType(String v){organisationType=v;} public String getWebsite(){return website;} public void setWebsite(String v){website=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getState(){return state;} public void setState(String v){state=v;} public String getPinCode(){return pinCode;} public void setPinCode(String v){pinCode=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getReviewedAt(){return reviewedAt;} public void setReviewedAt(Instant v){reviewedAt=v;}
}
